import { argosVitestPlugin } from '@argos-ci/storybook/vitest-plugin';
import { storybookTest } from '@storybook/addon-vitest/vitest-plugin';
import { playwright } from '@vitest/browser-playwright';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { defineConfig } from 'vitest/config';

const MINUTES_IN_MS = 60 * 1000;

const dirname =
  typeof __dirname !== 'undefined'
    ? __dirname
    : path.dirname(fileURLToPath(import.meta.url));

export default defineConfig({
  test: {
    projects: [
      {
        extends: './vite.config.ts',
        test: {
          name: 'unit',
          environment: 'jsdom',
          globals: true,
          include: [
            'src/**/*.{test,spec}.{ts,tsx}',
            'design-tokens/**/*.{test,spec}.{ts,tsx}',
          ],
          setupFiles: ['./setupTests.ts'],
          css: { modules: { classNameStrategy: 'non-scoped' } },
        },
      },
      {
        extends: './vite.config.ts',
        plugins: [
          storybookTest({
            configDir: path.join(dirname, '.storybook'),
            ...(process.env.STORYBOOK_URL
              ? { storybookUrl: process.env.STORYBOOK_URL }
              : {
                  storybookScript:
                    'bun run storybook:serve:dev:command --no-open',
                }),
          }),
          argosVitestPlugin({
            uploadToArgos: !!process.env.ARGOS_TOKEN,
            token: process.env.ARGOS_TOKEN,
            apiBaseUrl: process.env.ARGOS_API_BASE_URL,
            buildName: process.env.ARGOS_BUILD_NAME || undefined,
            branch: process.env.ARGOS_BRANCH || undefined,
            commit: process.env.ARGOS_COMMIT || undefined,
            referenceCommit: process.env.ARGOS_REFERENCE_COMMIT || undefined,
          }),
        ],
        test: {
          name: 'storybook',
          browser: {
            enabled: true,
            headless: true,
            provider: playwright({}),
            instances: [{ browser: 'chromium' }],
          },
          setupFiles: ['./.storybook/vitest.setup.ts'],
          testTimeout: 5 * MINUTES_IN_MS,
        },
      },
    ],
  },
});

const baseProject = {
  preset: '../../jest.preset.js',
  setupFilesAfterEnv: ['<rootDir>/test/setup-jest-dom.ts'],
  transformIgnorePatterns: [
    '/node_modules/(?!(twenty-ui|twenty-shared)/.*)',
    '../../node_modules/(?!(twenty-ui|twenty-shared)/.*)',
  ],
  transform: {
    '^.+\\.(ts|js|tsx|jsx|mjs)$': [
      '@swc/jest',
      {
        jsc: {
          parser: { syntax: 'typescript', tsx: true },
          transform: { react: { runtime: 'automatic' } },
        },
      },
    ],
  },
  moduleNameMapper: {
    '^@/(.*)$': '<rootDir>/src/$1',
    '^@lingui/core/macro$': '<rootDir>/test/lingui-macro-mock.ts',
  },
  moduleFileExtensions: ['ts', 'tsx', 'js', 'jsx', 'mjs'],
};

const jestConfig = {
  projects: [
    {
      ...baseProject,
      displayName: 'node',
      testEnvironment: 'node',
      testMatch: ['<rootDir>/src/**/*.test.ts'],
    },
    {
      ...baseProject,
      displayName: 'jsdom',
      testEnvironment: 'jsdom',
      testMatch: ['<rootDir>/src/**/*.test.tsx'],
    },
  ],
  coverageDirectory: './coverage',
};

export default jestConfig;

import { defineConfig } from 'vitest/config';

export default defineConfig({
  test: {
    root: 'packages/twenty-docs',
    include: ['scripts/**/*.spec.ts'],
    globals: true,
  },
});

import { defineConfig } from 'vitest/config';

export default defineConfig({
