import dotenv from 'dotenv';
import { type JestConfigWithTsJest, pathsToModuleNameMapper } from 'ts-jest';

import { NodeEnvironment } from 'src/engine/core-modules/twenty-config/interfaces/node-environment.interface';

import testTokens from './test/integration/constants/test-tokens.json';

const jestBabelTransform = require('./jest-babel-transform.cjs');

if (process.env.NODE_ENV === 'test') {
  dotenv.config({ path: '.env.test', override: true });
} else {
  dotenv.config({ path: '.env', override: true });
}

const isBillingEnabled = process.env.IS_BILLING_ENABLED === 'true';
const isClickhouseEnabled = process.env.CLICKHOUSE_URL !== undefined;

const tsConfig = require('./tsconfig.json');

const jestConfig: JestConfigWithTsJest = {
  // For more information please have a look to official docs https://jestjs.io/docs/configuration/#prettierpath-string
  // Prettier v3 should be supported in jest v30 https://github.com/jestjs/jest/releases/tag/v30.0.0-alpha.1
  prettierPath: null,
  silent: false,
  errorOnDeprecated: true,
  maxConcurrency: 1,
  moduleFileExtensions: ['js', 'mjs', 'json', 'ts'],
  rootDir: '.',
  testEnvironment: 'node',
  testPathIgnorePatterns: [
    ...(isBillingEnabled ? [] : ['<rootDir>/test/integration/billing']),
    ...(isClickhouseEnabled ? [] : ['<rootDir>/test/integration/audit']),
    // Requires an app booted as a secure deployment; run through
    // jest-integration-secure.config.ts (bunx vite-plus run twenty-server#test:integration:secure).
    '<rootDir>/test/integration/secure-deployment',
  ],
  testRegex: '\\.integration-spec\\.ts$',
  modulePathIgnorePatterns: ['<rootDir>/dist'],
  globalSetup: '<rootDir>/test/integration/utils/setup-test.ts',
  globalTeardown: '<rootDir>/test/integration/utils/teardown-test.ts',
  setupFilesAfterEnv: [
    '<rootDir>/test/integration/utils/setup-wait-for-all-jobs-between-tests.ts',
  ],
  testTimeout: 20000,
  maxWorkers: 1,
  // jsdom 29 and msw ship ESM-only transitive deps (parse5, entities,
  // tough-cookie, @exodus/bytes via html-encoding-sniffer, @csstools/@asamuzakjp
  // css engine, @mswjs/interceptors and friends), and ai, @ai-sdk/* and their
  // @workflow/serde dependency ship ESM only; let swc transform them
  // (and .mjs below) so jest can require them.
  transformIgnorePatterns: [
    '/node_modules/(?!(.*/node_modules/)?(jsdom|html-encoding-sniffer|whatwg-encoding|@exodus|parse5|entities|tough-cookie|@csstools|@asamuzakjp|msw|@mswjs|until-async|@bundled-es-modules|@open-draft|strict-event-emitter|headers-polyfill|outvariant|is-node-process|path-to-regexp|statuses|cookie|digest-fetch|md5|email-reply-parser|ai|@ai-sdk|@workflow|htmlparser2|domhandler|domutils|dom-serializer|domelementtype|@faker-js)/)',
  ],
  transform: {
    '^.+\\.(t|j|mj)s$': jestBabelTransform,
  },
  moduleNameMapper: {
    ...pathsToModuleNameMapper(tsConfig.compilerOptions.paths, {
      prefix: '<rootDir>/',
    }),
    '^test/(.*)$': '<rootDir>/test/$1',
  },
  globals: {
    APP_PORT: 4000,
    NODE_ENV: NodeEnvironment.TEST,
    // Test tokens are loaded from a shared JSON file to ensure consistency
    // with CI workflows and other tools that need these tokens
    ...testTokens,
  },
};

export default jestConfig;

import { type JestConfigWithTsJest } from 'ts-jest';

import jestIntegrationConfig from './jest-integration.config';

// Secure-deployment integration suite: same harness, but the app boots as a
// production https deployment. SERVER_URL is env-only configuration, so it
// must be set before the app is created in globalSetup; forcing it here keeps
// `bunx vite-plus run twenty-server#test:integration:secure` self-contained.
if (!(process.env.SERVER_URL ?? '').startsWith('https://')) {
  process.env.SERVER_URL = 'https://localhost:3000';
}

const jestConfig: JestConfigWithTsJest = {
  ...jestIntegrationConfig,
  testRegex: 'test/integration/secure-deployment/.*\\.integration-spec\\.ts$',
  testPathIgnorePatterns: [],
};

export default jestConfig;

import { createRequire } from 'module';
import jestBabelTransform from './jest-babel-transform.cjs';
const require = createRequire(import.meta.url);

const isCI = process.env.CI === 'true';

const jestConfig = {
  // For more information please have a look to official docs https://jestjs.io/docs/configuration/#prettierpath-string
  // Prettier v3 should be supported in jest v30 https://github.com/jestjs/jest/releases/tag/v30.0.0-alpha.1
  prettierPath: null,
  // to enable logs, comment out the following line
  silent: true,
  ...(isCI && { reporters: ['./jest-failures-only-reporter.js'] }),
  errorOnDeprecated: true,
  clearMocks: true,
  displayName: 'twenty-server',
  rootDir: './',
  testEnvironment: 'node',
  setupFilesAfterEnv: ['./setupTests.ts'],
  transformIgnorePatterns: [
    // jsdom 29 pulls ESM-only transitive deps (parse5, entities, tough-cookie,
    // @exodus/bytes via html-encoding-sniffer, @csstools/@asamuzakjp css engine),
    // and e2b/@e2b pull ESM-only chalk; ai, @ai-sdk/* and their @workflow/serde dependency ship ESM only.
    // sanitize-html >=2.17.6 pulls htmlparser2 12 (ESM-only, with its domhandler/domutils/dom-serializer/domelementtype chain),
    // @faker-js/faker 10 ships ESM only (it is a runtime dependency of the OpenAPI module and used by the metadata mocks);
    // nested under sanitize-html/node_modules because other consumers hold htmlparser2 8/10 at the root -- the optional
    // (.*/node_modules/)? prefix lets the allow-list match a package at any nesting depth, not only the hoisted copy.
    // jest's CJS runtime can't load their `export` syntax, so let swc transform them.
    '/node_modules/(?!(.*/node_modules/)?(file-type|@file-type|strtok3|token-types|@borewit|@tokenizer|uint8array-extras|read-next-line|digest-fetch|md5|js-sha256|js-sha512|base-64|charenc|crypt|email-reply-parser|jsdom|html-encoding-sniffer|whatwg-encoding|@exodus|parse5|entities|tough-cookie|@csstools|@asamuzakjp|graphql-upload|fs-capacitor|e2b|@e2b|chalk|ai|@ai-sdk|@workflow|htmlparser2|domhandler|domutils|dom-serializer|domelementtype|@faker-js|twenty-oxlint-rules)/)',
  ],
  testRegex: '.*\\.spec\\.ts$',
  transform: {
    '^.+\\.(t|j|mj)s$': jestBabelTransform,
  },
  moduleNameMapper: {
    '^src/(.*)': '<rootDir>/src/$1',
    '^test/(.*)': '<rootDir>/test/$1',
    '^file-type$': require.resolve('file-type'),
  },
  moduleFileExtensions: ['js', 'mjs', 'json', 'ts'],
  modulePathIgnorePatterns: ['<rootDir>/dist'],
  fakeTimers: {
    enableGlobally: true,
  },
  collectCoverageFrom: ['**/*.(t|j)s'],
  coverageDirectory: '../coverage',
};

export default jestConfig;

